    v.chunks_exact(17).map(|b| b[1])
}
fn main() {
    let mut bodies = vec![0.0; 34];
    bodies[1] = 1.0;
    bodies[18] = 2.0;
    println!("{:?}", ys(&bodies).collect::<Vec<_>>());
}

