    fn ids(&self) -> impl Iterator<Item = u32> + use<Self>;
}
struct World { n: u32 }
impl Bodies for World {
    fn ids(&self) -> impl Iterator<Item = u32> + use<> { 0..self.n }
}
fn main() {
    let mut w = World { n: 2 };
    let it = w.ids();
    w.n = 5;                       // allowed: `it` does not borrow `w`
    println!("{} {}", it.count(), w.n);
}

