// The associated const that suits static dispatch rules out a trait object.
fn pick(which: u32, a: &mut dyn Law, b: &mut dyn Law) -> bool {
    let mut body = [0.0; 3];
    if which == 0 { a.step(&mut body) } else { b.step(&mut body) }
}
